import os
import shutil
import parse
from litdata.streaming.client import S3Client
from typing import Queue, Dir


def _upload_fn(upload_queue: Queue, remove_queue: Queue, cache_dir: str, output_dir: Dir) -> None:

    s3 = S3Client()
    s3_client = s3.client()

    while True:
        item = upload_queue.get()
        if item is None:
            return

        if isinstance(item, str):
            local_path = item
        elif isinstance(item, tuple):
            temp_dir, local_path = item
        else:
            raise ValueError("Unsupported item type in upload queue")

        if not local_path.startswith(cache_dir):
            local_path = os.path.join(cache_dir, local_path)

        obj = parse.urlparse(output_dir)

        if obj.scheme == "s3":
            target_path = os.path.join(output_dir, os.path.basename(local_path))
            s3_client.upload_file(local_path, obj.netloc, target_path)

            if remove_queue:
                remove_queue.put(local_path)

        elif obj.scheme in ("file",):
            target_path = os.path.join(output_dir, os.path.basename(local_path))
            os.makedirs(os.path.dirname(target_path), exist_ok=True)
            shutil.move(local_path, target_path)

            if remove_queue:
                remove_queue.put(local_path)

        else:
            raise ValueError("Unsupported output directory scheme")
